package com.nexusgroup.restaurant.scheduler;

import static java.lang.Thread.currentThread;
import static org.instancio.Instancio.create;

import org.axonframework.commandhandling.gateway.CommandGateway;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;

import com.nexusgroup.restaurant.command.CreateFoodOrderCommand;

import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;

/**
 * DO NOT EDIT THIS FILE
 */
@Slf4j
@Component
@RequiredArgsConstructor
public class FoodOrderScheduler {

    private final CommandGateway commandGateway;

    @Scheduled(fixedRate = 15000, initialDelay = 1000)
    public void createRandomFoodOrder() {
        try {
            final var command = create(CreateFoodOrderCommand.class);
            commandGateway.send(command).get();
        } catch (Exception e) {
            log.error("Error during scheduled create food order command", e);
            currentThread().interrupt();
        }
    }
}
